func mean_absolute_deviation(numbers []float64) float64 {
    if len(numbers) == 0 {
        return 0.0
    }

    mean := calculateMean(numbers)
    mad := calculateMAD(numbers, mean)
    return mad
}

func calculateMean(numbers []float64) float64 {
    sum := 0.0
    for _, num := range numbers {
        sum += num
    }
    return sum / float64(len(numbers))
}

func calculateMAD(numbers []float64, mean float64) float64 {
    sumAbsDiff := 0.0
    for _, num := range numbers {
        diff := num - mean
        sumAbsDiff += math.Abs(diff)
    }
    return sumAbsDiff / float64(len(numbers))
}
