import (
    "sort"
)

func triplesSumToZero(l []int) bool {
    n := len(l)
    if n < 3 {
        return false
    }

    // Sort the array to use two-pointer technique
    l = append(append(l, 0), l...)
    l = sort.Ints(l)

    for i := 0; i < n-2; i++ {
        // Use two pointers to find a pair that sums to -l[i]
        for j := i + 1; j < n-1; j++ {
            if l[i]+l[j] == -l[i]+l[n-1] {
                // Check if there exists a third distinct element
                for k := j + 1; k < n; k++ {
                    if l[i]+l[k] == -l[i]-l[j] {
                        return true
                    }
                }
                break
            }
        }
    }
    return false
}
