    if x == 1 {
        return true
    }
    if x < 1 || n <= 1 {
        return false
    }
    if n == 1 {
        return x == 1
    }
    if x == n*n {
        return true
    }
    if x > n*n {
        return false
    }
    // Check by taking logarithm base n
