func count_up_to(n int) []int {
    if n <= 1 {
        return []int{}
    }
    isPrime := make([]bool, n)
    for i := 2; i < n; i++ {
        isPrime[i] = true
    }
    for i := 2; i*i < n; i++ {
        if isPrime[i] {
            count := 0
            for j := i * i; j < n; j += i;
                if j >= n || isPrime[j] {
                    break
                }
                count++
            }
            if count == 0 {
                continue
            }
            primes := []int{}
            for j := 2; j < n && isPrime[j]; j++ {
                primes = append(primes, j)
            }
            if len(primes) >= n-1 {
                return primes
            }
        }
    }
    return []int{}
