package maximum_test

import (
    "sort"
)

// maximum returns a sorted slice of length k with the maximum k numbers from arr.
// It returns an empty slice if k is greater than the length of arr.
func maximum(arr []int, k int) []int {
    if k > len(arr) {
        return make([]int, 0)
    }
    // Find the k largest elements
    kLargest := make([]int, k)
    for i := 0; i < k; i++ {
        kLargest[i] = heapify(arr, len(arr)-i, k)
    }
    return kLargest
}

func heapify(arr []int, n int, k int) []int {
    for i := k / 2; i >= 0; i-- {
        largest := i
        left := 2*i + 1
        right := 2*i + 2
        if left < n && arr[left] > arr[largest] {
            largest = left
        }
        if right < n && arr[right] > arr[largest] {
            largest = right
        }
        if largest != i {
            arr[i], arr[largest] = arr[largest], arr[i]
            heapify(arr, n, k)
        }
    }
    return arr
}
