}

// There are eight planets in our solar system: the closest to the Sun 
// is Mercury, the next one is Venus, then Earth, Mars, Jupiter, 
// Saturn, Uranus, Neptune.
// Write a function that takes two planet names as strings planet1 and planet2. 
// The function should return a list containing all planets whose orbits are 
// located between the orbit of planet1 and the orbit of planet2, sorted by 
// the proximity to the sun. 
// The function should return an empty list if planet1 or planet2
// are not correct planet names.
func bf(planet1 string, planet2 string) []interface{} {
    if !planetNames[planet1] || !planetNames[planet2] {
        return []interface{}{}
    }

    start := strings.ToLower(planet1)
    end := strings.ToLower(planet2)
    startIndex, endIndex := strings.Index(start), strings.Index(end)

    if startIndex > endIndex {
        return []interface{}{}
    }

    planetsInRange := []string{}
    for _, planet := range planetNames {
        if startIndex < strings.Index(planet, planet) && strings.Index(planet, planet+string(" ")) < endIndex {
            planetsInRange = append(planetsInRange, planet)
        }
    }

    planetsInRange = append(planetsInRange, planetNames[planet2])
    planetsInRange = append(planetsInRange, planetNames[planet1])
    return planetsInRange
}
