func do_algebra(operator []string, operand []int) int {
    // Convert operand list to a slice of numbers
    operands := make([]int, len(operand))
    for i, val := range operand {
        operands[i] = val
    }

    // Initialize result with the first operand
    result := operands[0]

    // Apply operators in sequence
    for i := 1; i < len(operands); i++ {
        op := operator[i-1]
        nextOperand := operands[i]
        switch op {
        case "+":
            result += operands[i]
        case "-":
            result -= operands[i]
        case "*":
            result *= nextOperand
        case "/":
            if nextOperand == 0 {
                panic("Division by zero")
            }
            result /= nextOperand
        case "^":
            result = int(pow(result, float64(nextOperand)))
        default:
            panic("Unknown operator")
        }
    }

    return result
}

func pow(base, exp int) int {
    result := 1
    for exp > 0 {
        result *= base
        exp--
    }
    return result
