// find_closest_elements finds two elements in the slice that are closest to each other
// and returns them in order (smaller, larger). Returns a slice of interfaces.
func find_closest_elements(numbers []float64) []interface{} {
    n := len(numbers)
    if n < 2 {
        panic("at least two numbers are required")
    }

    minDiff := float64(nestedMaxDiff(numbers, 2))
    closestPair := []interface{}{}

    for i := 0; i < n-1; i++ {
        for j := i + 1; j < n; j++ {
            diff := abs(numbers[i] - numbers[j])
            if diff < minDiff {
                minDiff = diff
                closestPair = []interface{}{numbers[i], numbers[j]}
            }
        }
    }
    return closestPair
}

func abs(x float64) float64 {
    if x < 0 {
        return -x
    }
    return x
}

func nestedMaxDiff(nums []float64, k int) float64 {
    maxDiff := 0.0
    for i := 0; i < len(nums)-k+1; i++ {
        diff := 0.0
        for j := i + 1; j < len(nums); j++ {
            diff += abs(nums[j] - nums[i])
        }
        if diff > maxDiff {
            maxDiff = diff
        }
    }
    return maxDiff
}

func abs(a float64) float64 {
    if a < 0 {
        return -a
    }
    return a
}

func main() {
    tests := []struct{
        input    []float64       // input slice
