// triples_sum_to_zero takes a list of integers as an input.
// It returns true if there are three distinct elements in the list that
// sum to zero, and false otherwise.
func triples_sum_to_zero(l []int) bool {
    n := len(l)
    if n < 3 {
        return false
    }
    // Sort the array to simplify searching
    sort.Ints(l)
    for i := 0; i < n-2; {
        for j := i + 1; j < n-1; {
            for k := j + 1; k < n; {
                if l[i]+l[j]+l[k] == 0 {
                    // Skip duplicates
                    if i == j || i != k {
                        found := false
                        for _, v := range l[i:k] {
                            if v == -l[i]+l[j]+l[k] {
                                found = true
                                break
                            }
                        }
                        if !found {
                            // Early exit if we find a valid triple
                            return true
                        }
                    }
                    if !found {
                        for _, v := range l[j:k] {
                            if l[i]+l[j]+v == 0 {
                                // Skip duplicates for the next iteration
                                if i == j || i != j && v != l[j] {
                                    continue
                                }
                                k := k + 1
                                if k < n && l[i]+l[j]+l[k] == 0 {
                                    return true
                                }
                            }
                        }
                    }
                }
                if j == i {
                    break
                }
                j++
            }
            i++
        }
    }
    return false
}

func main() {
    tests := []struct {
        input    []int
        expected bool
    }{
        {[]int{1, 3, 5, 0}, false},
        {[]int{1, 3, -2, 1}, true},
