package correct_bracketing_test

import (
    "testing"
    "reflect"
)

// brackets is a string of "<" and ">".
// return true if every opening bracket has a corresponding closing bracket.
// >>> correct_bracketing("<")
// false
// >>> correct_bracketing("<>")
// true
// >>> correct_bracketing("<<><>>")
// true
// >>> correct_bracketing("><<>")
// false
func correct_bracketing(brackets string) bool {
    balance := 0
    for _, ch := range brackets {
        if ch == "<" {
            balance++
        } else if ch == ">" {
            balance--
        }
        if balance < 0 {
            return false
        }
    }
    return balance == 0
}

// Tests
func main() {
    tests := []struct {
        input    string
        want     bool
    }{
        {"<", false},
        {"<>", true},
        {"<<><>>", true},
        {"><<>", false},
        {"<<><>>", true},
        {"<<<>>>", false},
    }

