// Given a positive integer N, return the total sum of its digits in binary.
// Example
// >>> solve(1000)
// "1"
// >>> solve(150)
// "110"
// >>> solve(147)
// "1100"
// Variables:
// @N integer
// Constraints: 0 ≤ N ≤ 10000.
// Output:
// a string of binary number
func solve(N int) string {
    sumDigits := 0
    for _, digit := range intToDigits(N) {
        sumDigits += int(byte(digit - '0') + 1)
    }
    binary := binaryToString(sumDigits)
    return string(binary)
