package sort_array_test

import (
    "reflect"
    "testing"
)

// sort_array implements the logic described in the problem statement.
// It sorts the array based on the sum of the first and last elements being odd or even.
func sort_array(array []int) []int {
    if len(array) < 2 {
        return array
    }

    first := array[0]
    last := array[len(array)-1]
    sum := first + last

    if reflect.DeepEqual(sum, 1) {
        // Odd sum -> ascending
        return sortArrayAscending(array)
    }
    if reflect.DeepEqual(sum, 0) {
        // Even sum -> descending
        return sortArrayDescending(array)
    }

    return nil // Should never reach here
}

func sortArrayAscending(array []int) []int {
    n := len(array)
    for i := 0; i < n-1; i++ {
        if array[i]+array[n-1-i] > 1 {
            swap(array, i, n-1-i)
        }
    }
    return array
}

func sortArrayDescending(array []int) []int {
    n := len(array)
    for i := 0; i < n-1; i++ {
        if array[i]+array[n-1-i] < 1 {
            swap(array, i, n-1-i)
        }
    }
    return array
}

func swap(a, i, j int) {
    a[i], a[j] = a[j], a[i]
}

func main() {
    // Test cases
    tests := []struct{
        input    []int
        expected []int
    }{
        {},
        {[]int{}, []int{}},
        {[]int{5}}, {[]int{5}},
        {[]int{2, 4, 3, 0, 1, 5}}, {[]int{0, 1, 2, 3, 4, 5}},
        {[]int{2, 4, 3, 0, 1, 5, 6}}, {[]int{6, 5, 4, 3, 2, 1, 0}}
    }

    for _, t := range tests {
        got := sort_array(t.input)
        if !reflect.DeepEqual(got, t.expected) {
            panic(fmt.Sprintf("Failed with input: %v, expected %v, got %v", t.input, t.expected, got))
        }
    }
}
