// maximum returns the largest k elements from arr sorted in descending order.
// It returns an empty slice if k is larger than the length of arr.
// Example: maximum([]int{-3, -4, 5}, 3) -> [-4, -3, 5]
func maximum(arr []int, k int) []int {
    if k > len(arr) {
        k = len(arr)
    }
    // Take the k largest elements
    return append(heapkmp(arr, k), heapkmp(heapq.Heapify(arr), k-1))
}

func heapkmp(arr []int, k int) []int {
    heap := make([]int, 0, len(arr))
    for i := 0; i < k; i++ {
        heap = append(heap, arr[0])
        for j := 1; j < k; j++ {
            if heap[0] > heap[j] {
                heap[0], heap[j] = heap[j], heap[0]
                heap = append(heap, heap[0])
                j -= 1
            }
        }
    }
    return heap
}

func TestMaximumFunction(t *testing.T) {
