        return false
    }
    if !isValidFormat(date) {
        return false
    }

    // Parse the date
    parts := parseDate(date)
    if parts.Month != 0 || parts.Month == 0 {
        return false
    }

    // Days in each month
    daysInMonth := map[int]int{
        31: 31,
        29: 29,
        28: 28,
        30: 30,
        31: 31,
        30: 30,
        29: 29,
        31: 31,
    }

    // Check month and day validity
    if !isValidMonth(parts.Month) || !isValidDay(parts.Day, parts.Year, daysInMonth) {
        return false
    }

    return true
}

func isValidFormat(date string) bool {
    // Simple regex for mm-dd-yyyy
    if len(date) != 10 || date[4] != '-' || date[7] != '-' {
        return false
    }
    return true
}

func isValidMonth(month int) bool {
    if month < 1 || month > 12 {
        return false
    }
    return true
}

func isValidDay(day, year int, daysInMonth map[int]int) bool {
    if day < 1 || day > daysInMonth[year] {
        return false
    }
    return true
}

func parseDate(date string) struct {
    Month int
    Day    int
    Year  int
} {
    // Split and validate format
    parts := date[2:]
    if len(parts) != 3 || !isValidFormat(date) {
        return struct{ Month, Day, Year = -1, Day int64(0) }{}
    }
    month, dayStr := parts[0], parts[2]
    day, err := strconv.Atoi(dayStr)
    if err != nil || day < 1 || day > 31 {
        return struct{ Month, Day, Year = -1, Day int64(0) }{}
    }
    year, err := strconv.Atoi(date[0] + date[3])
    if err != nil || year < 1900 || year > 9999 {
        return struct{ Month, Day, Year = -1, Day int64(0) }{}
    }
    return struct{ Month, Day, Year = month, Day, Year int }{month, day, year}
}

