// bf finds planets between two given planet names.
// It returns a sorted list of planets by proximity to the Sun.
func bf(planet1, planet2 string) []interface{} {
    if planet1 == planet2 {
        return []interface{}{planetOrbit[planet1]}
    }
    if !contains(planetOrbit, planet1) || !contains(planetOrbit, planet2) {
        return []interface{}{}
    }
    start := planetOrbit[planet1]
    end := planetOrbit[planet2]
    planetsInRange := []string{}
    for _, p := range planetOrbit {
        if start <= planetOrbit[p] && planetOrbit[p] <= end {
            planetsInRange = append(planetsInRange, p)
        }
    }
    planetsInRange = sortByKey(planetsInRange) // sort by proximity
    return planetsInRange
}

// Helper function to check if a slice contains a value.
func contains(slice []string, value string) bool {
    for _, v := range slice {
        if v == value {
            return true
        }
    }
    return false
}

