/// Check if in given vector of numbers, are any two numbers closer to each other than
/// given threshold.
/// 
/// # Arguments
/// - `numbers`: A vector of floating-point numbers.
/// - `threshold`: A threshold value to compare against.
/// 
/// # Returns
/// `true` if there exists at least one pair of numbers in `numbers`
/// whose difference is less than `threshold`, otherwise `false`.
fn has_close_elements(numbers: Vec<f64>, threshold: f64) -> bool {
    let mut max_diff = 0.0;
    let mut seen = HashMap::new();

    for &num in &numbers {
        let mut min_diff = f64::INFINITY;
        for &other in &numbers {
            if num != other {
                let diff = num - other;
                if diff < threshold {
                    max_diff = max(max_diff, diff);
                }
                if let Some(&min_diff) = seen.get(&other) {
                    if diff < min_diff {
                        max_diff = min_diff;
                    }
                }
                seen.insert(num, diff);
            }
        }
        // Update the maximum difference found so far
        max_diff = max(max_diff, max_diff, max_diff - num);
    }

    max_diff < threshold
}

