/// Function to check if brackets are correctly bracketed.
/// 
/// # Arguments
/// * `brackets` - A string containing "<" and ">" characters.
/// 
/// # Returns
/// * `true` if every opening bracket has a matching closing bracket.
/// * `false` otherwise.
fn correct_bracketing(brackets: String) -> bool {
    let mut stack = HashMap::new();
    let mut balance = 0;

    for ch in brackets.chars() {
        match ch {
            '>' => {
                balance += 1;
                stack.insert(ch, 1);
            }
            '<' => {
                balance -= 1;
                stack.insert(ch, -balance);
            }
            _ => {}
        }
    }

    balance == 0
}

