/// of length k with the maximum k numbers in arr.
/// 
/// The function returns the k largest elements in descending order.
fn maximum(arr: Vec<isize>, k: isize) -> Vec<isize> {
    let mut result = Vec::new();
    let mut filtered = arr.into_iter().filter(|&x| x > 0);
    let mut filtered: Vec<isize> = filtered.collect();
    filtered.sort_by(|a, b| b.cmp(a));
    if filtered.len() > k {
        filtered.squeeze(k).collect()
    } else {
