/// Validates a date string according to the specified rules.
/// 
/// The function uses the chrono library to parse and validate the date.
fn valid_date(date_str: String) -> bool {
    let date = NaiveDate::parse_from_str(&date_str, "%m-%d-%Y").unwrap();
    let mut parts = date.split('-');
    let (month, day, year) = parts;
    let month: i32 = month.parse().unwrap();
    let day: i32 = day.parse().unwrap();

    // Rule 1: Non-empty string
    if date_str.is_empty() {
        return false;
    }

    // Rule 2: Days range per month
    let valid_days = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 => 29, // leap year check not implemented here
        _ => 31,
    };
    if day < 1 || day > valid_days {
        return false;
    }

    // Rule 3: Month range
    if month < 1 || month > 12 {
        return false;
    }

    // Rule 4: Format check
    if date_str != format!("{:02}/{:02}/{:04}-{:02}/{:02}/{:04}"), 
        parts.len() == 5 {
        true
    } else {
        false
    }
}
