use std::str::Chars;

/// Given a string text, replace all spaces in it with underscores,
/// and if a string has more than 2 consecutive spaces, then replace all
/// consecutive spaces with -.
fn fix_spaces(text: String) -> String {
    let mut result = String::new();
    let mut chars = text.chars();
    let mut i = 0;

    while i < chars.len() {
        if chars.as_is(' ') {
            if i > 0 && chars.as_is(' ') == Some(&chars[i - 1]) && chars.as_is(' ') == Some(&chars[i - 2]) {
                if i + 1 < chars.len() && chars.as_is(' ') == Some(&chars[i + 1]) {
                    result.push('-');
                    i += 2;
                } else {
                    result.push('_');
                    i += 1;
                }
            } else {
                result.push(chars.as_whole().to_as_str());
                i += 1;
            }
        } else {
            result.push(chars.next().unwrap());
            i += 1;
        }
    }
    result
}

fn main() {
