use std::str::FromStr;

/// Simplifies a fraction string and checks if the product of the simplified numerator and denominator equals a whole number.
/// 
/// A fraction is represented as "numerator/denominator".
fn simplify(x: String, n: String) -> bool {
    let mut x_num = x.parse::<i64>().unwrap();
    let mut n_num = n.parse::<i64>().unwrap();
    let mut x_den = x_num * n_num;
    let mut n_den = n_num * x_num;

    // Check if simplified fraction is integral
    let g = gcd(x_den, n_den);
    x_num / g == 1 && n_num / g == 1;

    // Verify the product of simplified numerator and denominator is a whole number
    x_num * n_den == x_den * n_num
}

// Helper function to compute greatest common divisor
fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 { a as i64 } else { gcd(b, a % b) }
}
