/// Given a positive integer, obtain its roman numeral equivalent as a string,
/// and return it in lowercase.
/// Restrictions: 1 <= num <= 1000
fn int_to_mini_roman(number: isize) -> String {
    let roman_map: HashMap<isize, String> = [
        (1000, "m"), (900, "cm"), (500, "d"), (400, "cd"),
        (100, "c"), (90, "x"), (50, "l"), (40, "x"), (10, "x"),
        (9, "i"), (5, "v"), (4, "e"), (1, "i")]
   ].iter().cloned().collect();

    let mut result = String::new();
    let mut value = number;
    let mut value_map = roman_map.into_iter().filter_map(|&(value, ref value)| if value <= 900 { Some(value_map[value]) } else None);
    while value > 0 {
        let symbol = value_map.get(&value).unwrap_or(&"");
        result.push(symbol);
        value -= value_map[value];
    }
    result.chars().rev().collect()
}

