use std::collections::HashMap;

/// Given two vectors operator, and operand. The first vector has basic algebra operations,
/// and the second vector is a vector of integers. Use the two given vectors to build the algebraic
/// expression and return the evaluation of this expression.
/// The basic algebra operations:
/// Addition ( + ) 
/// Subtraction ( - ) 
/// Multiplication ( * ) 
/// Floor division ( // ) 
/// Exponentiation ( ** )
/// Example:
/// operator['+', '*', '-']
/// vector = [2, 3, 4, 5]
/// result = 2 + 3 * 4 - 5
/// => result = 9
fn do_algebra(operator: Vec<String>, operand: Vec<isize>) -> isize {
    let mut stack = Vec::new();
    let mut i = 0;

    for op in operator {
        match op.as_str() {
            "+" => stack.push(stack.pop().unwrap() + operand[i]),
            "-" => stack.push(stack.pop().unwrap() - operand[i]),
            "*" => stack.push(stack.pop().unwrap() * operand[i]),
            "//" => stack.push(stack.pop().unwrap() / operand[i]),
            "**" => stack.push(stack.pop().unwrap().pow(2)),
            _ => unreachable!(),
        }
        i += 1;
    }

    stack.pop().unwrap()
}
