function has_close_elements(numbers: number[], threshold: number): boolean {
    const n = numbers.length;
    for (let i = 0; i < n - 1; i++) {
        const diff = Math.abs(numbers[i] - numbers[i + 1]);
        if (diff > threshold) continue;
        const diff2 = Math.abs(numbers[i] - numbers[i + 2]);
        if (diff > threshold || diff2 > threshold) continue;
        if (diff <= threshold || diff2 <= threshold) return true;
    }
    return false;
}
