    dayMap.set(8, 31);
    dayMap.set(9, 30);
    dayMap.set(10, 31);
    dayMap.set(11, 30);
    dayMap.set(12, 31);

    if (dayMap.get(day) !== 1 || day < 1 || day > monthMap.get(month) || day > yearMap.get(year)) {
        return false;
    }

    if (monthMap.get(month) < day || monthMap.get(month) < 1 || day > monthMap.get(month) + 1) {
