function simplify(x: string, n: string): boolean {
    const [numX, denomX] = x.split('/').map(Number);
    const [numN, denomN] = n.split('/').map(Number);

    const gcd = gcd(numX * denomN, numX * denomX);
    const simplifiedX = numX / gcd;
    const simplifiedN = numN / gcd;

    return simplifiedX * simplifiedN === 1;
}

