function do_algebra(operator: string[], operand: number[]): number {
    let result: number = 0;
    let index = 0;
    const operandLength = operand.length - 1;

    for (let i = 0; i < operator.length; i++) {
        const op = operator[i];
        const operandIndex = operand.length - 1 - i;

        switch (op) {
            case '+':
                result += operand[operandIndex];
                break;
            case '-':
                result -= operand[operandIndex];
                break;
            case '*':
                result *= operand[operandIndex];
                break;
            case '/':
                result /= operand[operandIndex];
                break;
            case '**':
                result = Math.pow(result, operandIndex);
                break;
            default:
                throw new Error(`Unsupported operator: ${op}`);
        }
    }

    return result;
}
