// Full function implementation
function find_closest_elements(numbers: number[]): [number, number] {
  const n = numbers.length;
  if (n < 2) throw new Error("Array must contain at least two elements");

  let minDiff = Infinity;
  let result: [number, number] = [null, null];

  for (let i = 0; i < n - 1; i++) {
    const diff = Math.abs(numbers[i] - numbers[i + 1]);
    if (diff < minDiff) {
      minDiff = diff;
      result = [numbers[i], numbers[i + 1]];
    }
  }

  // If the closest pair is adjacent, return them in order
  if (Math.abs(numbers[i + 1] - numbers[i]) < Math.abs(numbers[i] - numbers[i + 2])) {
    result = [numbers[i], numbers[i + 1]];
  } else {
    result = [numbers[i + 1], numbers[i + 2]];
  }

  return result;
}
