// For a given number n, find the largest number that divides n evenly, smaller than n
// >>> largest_divisor(15)
// 5
function largest_divisor(n: number): number {
  if (n <= 1) return 1;
  for (let i = Math.floor(Math.sqrt(n)); i < n; i++) {
    if (n % i === 0) {
      if (i === n / i) return i;
      if (n / i !== i) return largest_divisor(n / i);
    }
  }
  return n - 1;
}
