// Full function implementation
function triples_sum_to_zero(l: number[]): boolean {
  const n = l.length;
  if (n < 3) return false;

  // Sort the array to simplify searching
  const sorted = l.sort((a, b) => a - b);
  let found = false;

  // Use three nested loops with early exit
  for (let i = 0; i < n - 2; i++) {
    for (let j = i + 1; j < n - 1; j++) {
      for (let k = j + 1; k < n; k++) {
        const sum = sorted[i] + sorted[j] + sorted[k];
        if (sum === 0) {
          found = true;
          break;
        }
        if (sum < 0) break; // Early exit if sum is negative
      }
      if (found) return true;
    }
    if (found) break;
  }
  return false;
}
