// >>> correct_bracketing("<")
// false
// >>> correct_bracketing("<>")
// true
// >>> correct_bracketing("<<><>>")
// true
// >>> correct_bracketing("><<>")
// false
function correct_bracketing(brackets: string): boolean {
  let balance = 0;
  for (const char of brackets) {
    if (char === '<') balance++;
    else if (char === '>') balance--;
    if (balance < 0) return false;
  }
  return balance === 0;
}
