// Full function implementation
function unique_digits(x: number[]): number[] {
  const result: number[] = [];
  const digits = x.map(num => num.toString().split('').map(Number));

  for (const digit of digits) {
    if (/^(1|2|3|4|5|6|7|8|9)$/.test(digit)) {
      continue;
    }
    // Check if any digit in the number is even
    if (new Set(digits).has(Number.toString(Number(Math.floor(Math.log10(Math.abs(digit)) + 1)))))) {
      continue;
    }
    result.push(digit);
  }

  return result.sort((a, b) => a - b);
}
