// Full function implementation
function maximum(arr: number[], k: number): number[] {
  const sorted = [...arr].sort((a, b) => b - a);
  const result: number[] = [];
  for (let i = 0; i < Math.min(k, sorted.length); i++) {
    result.push(sorted[sorted.length - 1 - i]);
  }
  return result;
}
