// The full function implementation
function valid_date(date: string): boolean {
  const parts = date.split('-');
  if (parts.length !== 3 || !parts[2].match(/\d{4}/)) return false;
  const [month, day, year] = parts;

  // Check month range
  const monthIndex = parseInt(month);
  const monthDays = {
    1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30,
    7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31
  };

  // Check day range based on month
  const dayRange = monthIndex === 2 ? 29 : monthDays[monthIndex];
  const dayIndex = parseInt(day);
  if (dayIndex < 1 || dayIndex > dayRange) return false;

  // Validate format and other rules
  if (!dayIndex.toString().match(/\d{1,2}/)) return false;
  return dayIndex >= 1 && dayIndex <= dayRange;
}

