// The full function implementation
function prod_signs(arr: number[]): number | undefined {
    if (arr.length === 0) return undefined;

    let productOfSigns = 1;
    let sumOfMagnitudes = 0;

    for (const num of arr) {
        const sign = num > 0 ? 1 : -1;
        const magnitude = Math.abs(num);
        productOfSigns *= sign;
        sumOfMagnitudes *= magnitude;
    }

    // The final result is productOfSigns * sumOfMagnitudes
    return productOfSigns * sumOfMagnitudes;
}
