// Full function implementation
function largest_smallest_integers(lst: number[]): [number | undefined, number | undefined] {
  const negatives = lst.filter(n => n < 0);
  const positives = lst.filter(n => n > 0);

  const largestNeg = negatives.length > 0 ? Math.max(...negatives) : undefined;
  const smallestPos = positives.length > 0 ? Math.min(...positives) : undefined;

  return [largestNeg, smallestPos];
}
