// Full function implementation
function simplify(x: string, n: string): boolean {
  // Parse the fraction strings into numerator and denominator
  const [numX, denomX] = x.split('/').map(Number);
  const [numN, denomN] = n.split('/').map(Number);

  // Simplify x/n by reducing both numerator and denominator
  const simplifiedX = numX / Math.gcd(numX, denomX);
  const simplifiedN = denomN / Math.gcd(numN, denomN);

  // Check if the simplified fraction equals the original simplified form
  return simplifiedX * simplifiedN === numX * simplifiedN;
}

