// Full function implementation
function do_algebra(operator: string[], operand: number[]): number {
  let result = 0;
  let index = 0;
  let operatorIndex = 0;

  // Iterate through operands and operators
  while (index < operand.length - 1) {
    const op = operator[index];
    const operandValue = operand[index + 1];
    const nextOperand = operand[index + 2];

    switch (op) {
      case '+': result += operandValue; break;
      case '-': result -= operandValue; break;
      case '*': result *= operandValue; break;
      case '/': result = Math.floor(result / operandValue); // floor division
      case '^': result = Math.pow(result, nextOperand); break;
      default: throw new Error(`Unknown operator: ${op}`);
    }
    index++;
    operatorIndex++;
  }

  return result;
}
```

